<title>Biomedical Research Landscape 2024–2026</title>
<script src="https://cdn.jsdelivr.net/npm/chart.js@4.4.1/dist/chart.umd.min.js"></script>
<style>
  :root {
    --primary: #1a5276;
    --secondary: #2874a6;
    --accent: #148f77;
    --warning: #d68910;
    --danger: #c0392b;
    --bg: #f8f9fa;
    --card: #ffffff;
    --text: #2c3e50;
    --muted: #5d6d7e;
    --border: #e5e8e8;
  }
  * { box-sizing: border-box; }
  body {
    font-family: -apple-system, BlinkMacSystemFont, "Segoe UI", Roboto, "Helvetica Neue", Arial, sans-serif;
    background: var(--bg);
    color: var(--text);
    line-height: 1.6;
    margin: 0;
    padding: 0;
  }
  .container {
    max-width: 1200px;
    margin: 0 auto;
    padding: 24px;
  }
  header {
    background: linear-gradient(135deg, var(--primary) 0%, var(--secondary) 100%);
    color: white;
    padding: 48px 24px;
    border-radius: 12px;
    margin-bottom: 32px;
    box-shadow: 0 4px 20px rgba(0,0,0,0.1);
  }
  header h1 { margin: 0 0 12px; font-size: 2.2rem; font-weight: 700; }
  header p { margin: 0; opacity: 0.9; font-size: 1.05rem; }
  .meta { font-size: 0.9rem; opacity: 0.8; margin-top: 12px; }
  .toc {
    background: var(--card);
    border-radius: 10px;
    padding: 24px;
    margin-bottom: 32px;
    box-shadow: 0 2px 8px rgba(0,0,0,0.04);
    border: 1px solid var(--border);
  }
  .toc h2 { margin-top: 0; font-size: 1.2rem; color: var(--primary); }
  .toc ul { columns: 2; column-gap: 32px; margin: 0; padding-left: 20px; }
  .toc li { margin-bottom: 6px; }
  .toc a { color: var(--secondary); text-decoration: none; }
  .toc a:hover { text-decoration: underline; }
  .kpi-grid {
    display: grid;
    grid-template-columns: repeat(auto-fit, minmax(200px, 1fr));
    gap: 20px;
    margin-bottom: 32px;
  }
  .kpi-card {
    background: var(--card);
    border-radius: 10px;
    padding: 24px;
    text-align: center;
    box-shadow: 0 2px 8px rgba(0,0,0,0.04);
    border: 1px solid var(--border);
    transition: transform 0.15s ease;
  }
  .kpi-card:hover { transform: translateY(-2px); }
  .kpi-value { font-size: 2rem; font-weight: 700; color: var(--primary); }
  .kpi-label { font-size: 0.85rem; color: var(--muted); margin-top: 4px; text-transform: uppercase; letter-spacing: 0.5px; }
  .kpi-sub { font-size: 0.8rem; color: var(--muted); margin-top: 4px; }
  section {
    background: var(--card);
    border-radius: 10px;
    padding: 32px;
    margin-bottom: 24px;
    box-shadow: 0 2px 8px rgba(0,0,0,0.04);
    border: 1px solid var(--border);
  }
  section h2 {
    color: var(--primary);
    font-size: 1.4rem;
    margin-top: 0;
    margin-bottom: 16px;
    padding-bottom: 10px;
    border-bottom: 2px solid var(--border);
  }
  section h3 {
    color: var(--secondary);
    font-size: 1.1rem;
    margin-top: 24px;
    margin-bottom: 12px;
  }
  p { margin: 0 0 12px; }
  .chart-container {
    position: relative;
    height: 360px;
    margin: 20px 0;
  }
  .chart-container.small { height: 280px; }
  table {
    width: 100%;
    border-collapse: collapse;
    margin: 16px 0;
    font-size: 0.92rem;
  }
  th, td {
    padding: 10px 12px;
    text-align: left;
    border-bottom: 1px solid var(--border);
  }
  th {
    background: #f4f6f7;
    font-weight: 600;
    color: var(--primary);
  }
  tr:hover { background: #f9fafb; }
  .text-right { text-align: right; }
  .text-center { text-align: center; }
  .badge {
    display: inline-block;
    padding: 3px 10px;
    border-radius: 12px;
    font-size: 0.78rem;
    font-weight: 600;
  }
  .badge-success { background: #d4efdf; color: #1e8449; }
  .badge-warning { background: #fdebd0; color: #b9770e; }
